CREATE TABLE document_row(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,kind TEXT NOT NULL,ordinal INTEGER NOT NULL,native_id TEXT NOT NULL,source_path TEXT NOT NULL,pointer TEXT NOT NULL,raw_json TEXT NOT NULL,UNIQUE(source_path,ordinal)) WITHOUT ROWID;
CREATE TABLE document_slot(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES document_row(id),field TEXT NOT NULL,locale TEXT NOT NULL,raw_locator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous')),UNIQUE(row_id,field,locale)) WITHOUT ROWID;
CREATE TABLE document_text(id TEXT PRIMARY KEY,slot_id TEXT NOT NULL REFERENCES document_slot(id),source_path TEXT NOT NULL,pair_ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,raw_text TEXT NOT NULL,UNIQUE(slot_id,source_path,pair_ordinal)) WITHOUT ROWID;
CREATE TABLE document_relation(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES document_row(id),origin_pointer TEXT NOT NULL,kind TEXT NOT NULL,source_path TEXT NOT NULL,pointer TEXT NOT NULL,raw_value TEXT NOT NULL,boundary TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous','mapping_unresolved')),candidate_count INTEGER NOT NULL CHECK(candidate_count>=0),search_complete INTEGER NOT NULL CHECK(search_complete IN (0,1)),UNIQUE(row_id,origin_pointer,kind,source_path,pointer)) WITHOUT ROWID;
CREATE TABLE document_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL REFERENCES document_relation(id),target_source_path TEXT NOT NULL,target_pointer TEXT NOT NULL,target_seal_json TEXT NOT NULL,UNIQUE(relation_id,target_source_path,target_pointer)) WITHOUT ROWID;
CREATE TABLE document_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE INDEX document_slot_parent ON document_slot(row_id);
CREATE INDEX document_text_slot ON document_text(slot_id);
CREATE INDEX document_relation_parent ON document_relation(row_id);
CREATE INDEX document_candidate_relation ON document_candidate(relation_id);
CREATE TRIGGER document_row_i BEFORE INSERT ON document_row WHEN EXISTS(SELECT 1 FROM document_row WHERE id=NEW.id OR (source_path=NEW.source_path AND ordinal=NEW.ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_row_update BEFORE UPDATE ON document_row BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_row_delete BEFORE DELETE ON document_row BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_slot_i BEFORE INSERT ON document_slot WHEN EXISTS(SELECT 1 FROM document_slot WHERE id=NEW.id OR (row_id=NEW.row_id AND field=NEW.field AND locale=NEW.locale)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_slot_update BEFORE UPDATE ON document_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_slot_delete BEFORE DELETE ON document_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_text_i BEFORE INSERT ON document_text WHEN EXISTS(SELECT 1 FROM document_text WHERE id=NEW.id OR (slot_id=NEW.slot_id AND source_path=NEW.source_path AND pair_ordinal=NEW.pair_ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_text_update BEFORE UPDATE ON document_text BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_text_delete BEFORE DELETE ON document_text BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_relation_i BEFORE INSERT ON document_relation WHEN EXISTS(SELECT 1 FROM document_relation WHERE id=NEW.id OR (row_id=NEW.row_id AND origin_pointer=NEW.origin_pointer AND kind=NEW.kind AND source_path=NEW.source_path AND pointer=NEW.pointer)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_relation_update BEFORE UPDATE ON document_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_relation_delete BEFORE DELETE ON document_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_candidate_i BEFORE INSERT ON document_candidate WHEN EXISTS(SELECT 1 FROM document_candidate WHERE id=NEW.id OR (relation_id=NEW.relation_id AND target_source_path=NEW.target_source_path AND target_pointer=NEW.target_pointer)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_candidate_update BEFORE UPDATE ON document_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_candidate_delete BEFORE DELETE ON document_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER document_release_i BEFORE INSERT ON document_release WHEN EXISTS(SELECT 1 FROM document_release) BEGIN SELECT RAISE(ABORT,'immutable release');END;
CREATE TRIGGER document_release_update BEFORE UPDATE ON document_release BEGIN SELECT RAISE(ABORT,'immutable release');END;
CREATE TRIGGER document_release_delete BEFORE DELETE ON document_release BEGIN SELECT RAISE(ABORT,'immutable release');END;
